  } catch (e: Throwable) {
    // ts: packages/translate/harness/harness.ts:722
    if ((e is HarnessError)) {
      return ("[\"harness-error\"," + harness_q((e as HarnessError).detail) + "]")
    }
    return "[\"threw\"]"
  }
}
